/* BTEC Level 3 IT Unit 2 — RA10 practice papers in the 2025 AAQ sample-assessment layout:
   one scenario, four questions (22 / 23 / 23 / 22 marks), each ending in a 9-mark evaluation. */
(function () {
  'use strict';
  const L9 = (window.BIZ_LEVELS || {})[9] || null;
  function Q(n, ctx, parts) {
    return parts.map((p, i) => ({
      q: n, sub: p[0], marks: p[1], section: 'Q' + n, ctx: i === 0 ? ctx : [], text: p[2], diagram: !!(p[4] && p[4].diagram),
      ms: Object.assign({ body: p[3], levels: p[1] >= 9 ? L9 : null }, p[4] || {})
    }));
  }
  const L = (...lines) => lines.join('\n');
  const EVAL = 'Levels-based: credit relevant points applied to the scenario, balance and a supported conclusion. Indicative content:';
  const RA = (n, title, blurb, qs) => {
    const items = [].concat(...qs);
    return { id: 'IT2-R' + String(n).padStart(2, '0'), unit: 2, key: 'R' + String(n).padStart(2, '0'), source: 'ra10', series: 'RA10 Paper ' + n, date: 'RA10 practice paper ' + n, title, blurb, kind: 'exam', minutes: 135, items, total: items.reduce((s, x) => s + x.marks, 0) };
  };

  const papers = [];

  /* ───────────── Paper 1: GP clinics, ransomware ───────────── */
  papers.push(RA(1, 'Northgate Health Clinics', 'Three GP clinics: ransomware, patient data, GDPR, segmentation and an incident response plan.', [
    Q(1, [
      'Northgate Health Clinics',
      'Northgate Health runs three GP clinics in the same town. Each clinic has a reception area with a public waiting room, consultation rooms and a small office.',
      'Patient records are held on a database server at the main clinic. The other two clinics connect to it over the internet. Doctors use laptops in consultation rooms; receptionists use desktop PCs.',
      'Patients can book appointments through the clinic website, which is hosted on a web server at the main clinic.',
      'Last month a receptionist opened an email attachment and ransomware encrypted the shared drive.'
    ], [
      ['a(i)', 2, 'Draw a network diagram for the main clinic showing the router, a firewall, a switch, the database server, the web server placed in a DMZ, and the PCs and laptops.', L('Award one mark for each, up to two marks:', '• firewall shown between the router / internet and the internal switch (1)', '• web server shown in a separate DMZ / segment, not on the internal LAN with the database server (1)', 'Accept a second firewall / firewall with three interfaces to create the DMZ.'), { diagram: true }],
      ['a(ii)', 2, 'Explain one reason why the web server should be placed in a demilitarised zone (DMZ).', L('Award one mark for a reason and one for a linked expansion:', '• the web server must be reachable from the internet (1) so if it is compromised the attacker cannot reach the patient database on the internal network (1)', '• limits the traffic allowed into the internal network (1) as only specific ports / services pass from the DMZ (1)')],
      ['a(iii)', 2, 'Explain one way the two smaller clinics could connect securely to the database server.', L('Award one mark for a method and one for a linked expansion:', '• site-to-site VPN (1) so data is encrypted as it travels over the internet (1)', '• leased line / private WAN (1) so traffic does not travel over the public internet (1)')],
      ['b(i)', 1, 'State what is meant by ransomware.', L('Award one mark:', '• malware that encrypts / locks files or systems and demands payment to restore access (1)')],
      ['b(ii)', 2, 'Explain one reason why the clinic should not pay the ransom.', L('Award one mark for a reason and one for a linked expansion:', '• there is no guarantee the files will be decrypted (1) so the money could be lost and data still not recovered (1)', '• paying funds criminal activity (1) and marks the clinic as a target for future attacks (1)')],
      ['c', 4, 'Describe one technical countermeasure that would reduce the chance of a ransomware attack spreading from a receptionist’s PC, and how it works.', L('Award one mark for each point in a linked description, up to four marks:', '• identify a countermeasure e.g. least-privilege access rights / network segmentation / application whitelisting / email attachment filtering (1)', '• how it is set up e.g. receptionists given read-only / no access to shared clinical folders via group policy (1)', '• what it does e.g. malware runs with the user’s permissions (1)', '• how it reduces the threat e.g. so it cannot encrypt files the user cannot write to (1)')],
      ['d', 9, 'Northgate Health currently backs up the database server every night to a NAS drive in the server cupboard at the main clinic. Evaluate the suitability of this backup approach for protecting the clinics against ransomware.', L(EVAL, '• nightly backups mean at most one day of data is lost', '• the NAS is on the same network – ransomware can encrypt network-attached backups too', '• no off-site / offline / immutable copy; fire or theft at the main clinic loses both', '• no mention of testing restores – backups may not work when needed', '• should follow 3-2-1: three copies, two media, one off-site / offline (e.g. cloud with versioning, rotated offline drive)', '• recovery time matters for patient care – the RTO must be defined', '• patient data in backups must be encrypted (UK GDPR)', 'Conclusion: partly suitable but not enough against ransomware without an offline / off-site, tested copy.')]
    ]),
    Q(2, ['After the attack, the practice manager is reviewing how Northgate Health meets its legal responsibilities for patient data.'], [
      ['a(i)', 1, 'State the name of the law that controls how organisations in the UK process personal data.', L('Award one mark:', '• UK General Data Protection Regulation (UK GDPR) / Data Protection Act 2018 (1)')],
      ['a(ii)', 1, 'State the name of the law that makes unauthorised access to computer material an offence.', L('Award one mark:', '• Computer Misuse Act 1990 (1)')],
      ['a(iii)', 2, 'Explain one GDPR principle the clinics must follow when storing patient records.', L('Award one mark for the principle and one for a linked expansion:', '• integrity and confidentiality / security (1) so records must be protected against unauthorised access / loss, e.g. encryption (1)', '• storage limitation (1) records are kept only as long as needed (1)', '• accuracy (1) records must be kept up to date (1)', '• data minimisation (1) only collect what is needed for care (1)')],
      ['b', 3, 'Describe what Northgate Health must do now that patient data may have been affected by the ransomware attack.', L('Award one mark for each point, up to three marks:', '• assess whether personal data was accessed / lost (1)', '• report the breach to the ICO within 72 hours if there is a risk to individuals (1)', '• inform affected patients without undue delay if the risk is high (1)', '• record the breach and actions taken (1)')],
      ['c(i)', 3, 'Doctors’ laptops store copies of patient letters. Describe how full-disk encryption protects this data if a laptop is stolen.', L('Award one mark for each point, up to three marks:', '• all data on the drive is encrypted (1)', '• a key / password / TPM is needed at start-up to decrypt it (1)', '• without the key the thief only sees unreadable data (1)', '• so the theft may not count as a reportable breach of readable data (1)')],
      ['c(ii)', 2, 'State two other security measures for the doctors’ laptops.', L('Award one mark for each, up to two marks:', '• strong password / biometric login (1)', '• automatic screen lock (1)', '• remote wipe / device tracking (1)', '• up-to-date antivirus / patches (1)', '• cable lock (1)')],
      ['d', 2, 'Explain why the receptionists’ screens should not be visible from the waiting room.', L('Award one mark for a reason and one for expansion:', '• shoulder surfing (1) patients could read other patients’ personal / medical data, a GDPR breach (1)')],
      ['e', 9, 'Northgate Health is considering role-based access control (RBAC) for the patient database instead of giving each member of staff individual permissions (discretionary access control). Evaluate the use of RBAC at Northgate Health.', L(EVAL, '• roles such as doctor, nurse, receptionist, manager match the clinics’ job types', '• new staff get the right access quickly by being added to a role; leavers removed easily', '• supports least privilege – receptionists see appointments, not clinical notes', '• easier to audit who can see what (GDPR accountability)', '• roles must be designed carefully; too broad roles give too much access', '• exceptions (e.g. locum doctors, staff covering two roles) need managing', '• DAC is flexible but error-prone and hard to manage across three sites', 'Conclusion: RBAC is likely more secure and manageable for Northgate.')]
    ]),
    Q(3, ['The IT support company that looks after Northgate Health has produced a list of vulnerabilities after a scan of the network.'], [
      ['a', 2, 'Give two vulnerability assessment tools the IT support company could use.', L('Award one mark for each, up to two marks:', '• port scanner (1)', '• network mapper e.g. Nmap (1)', '• website vulnerability scanner (1)', '• vulnerability detection software e.g. Nessus / OpenVAS (1)', '• registry checker (1)')],
      ['b', 3, 'The scan found that port 3389 (Remote Desktop) is open to the internet on a reception PC. Describe how an attacker could use this vulnerability.', L('Award one mark for each point in a linked description, up to three marks:', '• the attacker scans the internet / clinic IP for open RDP ports (1)', '• tries a brute-force / dictionary attack or stolen credentials (1)', '• logs in remotely and controls the PC / installs ransomware / moves across the network (1)')],
      ['c', 3, 'Describe how penetration testing differs from a vulnerability scan.', L('Award one mark for each point, up to three marks:', '• a vulnerability scan automatically lists known weaknesses (1)', '• a penetration test actively tries to exploit weaknesses (1)', '• like a real attacker, within an agreed scope / with permission (1)', '• producing a report showing how far an attacker could get and recommendations (1)')],
      ['d', 2, 'Explain one reason why the clinic should use an independent third party for the penetration test.', L('Award one mark for a reason and one for expansion:', '• independent testers have no conflict of interest (1) so they report problems honestly / including the support company’s mistakes (1)', '• specialist skills / certification (1) gives assurance the test is thorough (1)')],
      ['e(i)', 2, 'The scan also found that the clinic’s router still uses the manufacturer’s default admin password. Explain why this is a vulnerability.', L('Award one mark for a reason and one for expansion:', '• default passwords are published online / well known (1) so an attacker can log in and change the router settings / open ports (1)')],
      ['e(ii)', 2, 'State two sources of information about new vulnerabilities in the clinic’s systems.', L('Award one mark for each, up to two marks:', '• manufacturer’s website / security advisories (1)', '• NCSC / NIST / OWASP (1)', '• forums / third-party security websites (1)', '• CVE databases (1)')],
      ['f', 9, 'The practice manager has suggested accepting some of the lower-risk vulnerabilities, transferring other risks by buying cyber insurance, and avoiding the risk from remote access by banning it. Evaluate these passive risk management approaches for Northgate Health.', L(EVAL, 'Risk acceptance:', '• sensible for low-impact, low-likelihood risks where fixing costs more than the loss', '• must be documented and reviewed; patient data risks are rarely “low”', 'Risk transfer (insurance):', '• covers financial loss, recovery costs, legal advice', '• does not stop the attack, protect patients or cover reputational loss; may require minimum controls', 'Risk avoidance (banning remote access):', '• removes the RDP attack vector completely', '• but doctors may need remote access (home visits, out-of-hours) – a secure VPN with MFA may be better', 'Conclusion: a mix is appropriate, but technical controls are still needed alongside passive measures.')]
    ]),
    Q(4, ['Northgate Health is writing a cyber security incident response policy.'], [
      ['a', 2, 'Give two items that should be included in an incident response policy.', L('Award one mark for each, up to two marks:', '• contact list / who to inform (1)', '• roles and responsibilities (1)', '• procedures / flowcharts for different incident types (1)', '• communication plan (internal / patients / ICO) (1)', '• how incidents are recorded and reviewed (1)')],
      ['b(i)', 2, 'Explain one reason why the policy should include a flowchart.', L('Award one mark for a reason and one for expansion:', '• staff can follow the steps quickly under pressure (1) so the right actions are taken in the right order (1)')],
      ['b(ii)', 2, 'Explain why the receptionist’s PC should be disconnected from the network, but not switched off, when ransomware is discovered.', L('Award one mark for each linked point:', '• disconnecting stops the ransomware spreading to other devices / the server (1)', '• leaving it on preserves volatile evidence in RAM, e.g. running processes / encryption keys (1)')],
      ['c(i)', 2, 'The IT support company carries out live forensics on the receptionist’s PC. Explain one challenge of live forensics.', L('Award one mark for a challenge and one for expansion:', '• any action on a running system changes it (1) so evidence may be altered and must be recorded carefully (1)', '• the malware may still be active (1) and could delete evidence / spread (1)')],
      ['c(ii)', 3, 'Describe how the investigator should document the scene before collecting evidence.', L('Award one mark for each point, up to three marks:', '• photograph the screen and the PC / connections (1)', '• record date, time, who is present and what is visible (1)', '• note the state of the device (on / off, logged in, network cables) (1)', '• start a chain of custody record for anything removed (1)')],
      ['d', 2, 'Explain why a hash value is calculated for the forensic image of the PC’s drive.', L('Award one mark for an identification and one for expansion:', '• the hash is a unique fingerprint of the data (1) so it can be shown later that the image has not been altered (1)')],
      ['e', 9, 'After the investigation, the IT support company will write a security report for Northgate Health. Evaluate how the report could be used to prevent a similar incident happening again.', L(EVAL, '• report structure: summary, timeline, how the attack happened, impact, evidence, recommendations', '• identifies the root cause (phishing email, excessive permissions, backup weaknesses)', '• recommendations: staff phishing training, email filtering, least privilege, offline backups, patching, MFA', '• feeds into updating IT policies (incident response, backup, acceptable use) – Plan-Do-Check-Act', '• evidence for the ICO / insurers that lessons have been learned', '• only effective if the clinics act on it, fund changes and audit compliance later', '• must be written so non-technical managers understand it', 'Conclusion: valuable if recommendations are prioritised, owned and reviewed.')]
    ])
  ]));

  /* ───────────── Paper 2: Online retailer ───────────── */
  papers.push(RA(2, 'Kestrel Outdoor (online retailer)', 'An online outdoor-gear shop: DDoS, cloud hosting, phishing, encryption, NAT and backup policy.', [
    Q(1, [
      'Kestrel Outdoor',
      'Kestrel Outdoor sells camping and hiking equipment online. It has 40 staff: 25 in a warehouse and 15 in an office above it.',
      'The online shop is hosted by a cloud provider. Orders are passed to the warehouse system over the internet.',
      'Office staff often work from home two days a week using company laptops.',
      'Kestrel takes card payments through a third-party payment provider.'
    ], [
      ['a(i)', 2, 'Kestrel’s website uses HTTPS. Explain how HTTPS protects customers’ details.', L('Award one mark for each linked point:', '• data between the browser and the server is encrypted using TLS (1)', '• so intercepted details (e.g. addresses / logins) cannot be read (1)', 'Accept: the digital certificate confirms the site is genuine (1).')],
      ['a(ii)', 2, 'Explain one difference between symmetric and asymmetric encryption.', L('Award up to two marks:', '• symmetric uses the same key to encrypt and decrypt (1) whereas asymmetric uses a public key to encrypt and a private key to decrypt (1)')],
      ['a(iii)', 2, 'Explain why asymmetric encryption is used at the start of an HTTPS session.', L('Award up to two marks:', '• to exchange / agree a symmetric session key securely (1) without the key being sent in plain form over the internet (1)', 'Accept: symmetric encryption is then used because it is faster (1).')],
      ['b(i)', 1, 'State what is meant by a DDoS attack.', L('Award one mark:', '• many devices (often a botnet) flood a server / service with traffic so it cannot respond to genuine users (1)')],
      ['b(ii)', 2, 'Explain one impact on Kestrel Outdoor of a DDoS attack on its website.', L('Award one mark for an impact and one for expansion:', '• lost sales (1) as customers cannot place orders while the site is down (1)', '• reputational loss (1) customers may shop with competitors instead (1)')],
      ['c', 4, 'Describe one way Kestrel and its cloud provider could protect the website against DDoS attacks.', L('Award one mark per point in a linked description, up to four marks:', '• use a DDoS protection / CDN service (1)', '• traffic passes through the provider’s network first (1)', '• which detects and filters malicious traffic / rate limits requests (1)', '• so only genuine requests reach the web server / the load is spread across many servers (1)')],
      ['d', 9, 'Evaluate the security implications for Kestrel Outdoor of using a cloud provider to host its online shop rather than its own web server.', L(EVAL, '• provider has specialist security staff, patching, physical security, DDoS protection', '• scalable capacity helps absorb attacks and busy periods', '• shared responsibility: Kestrel is still responsible for its accounts, configuration and data', '• misconfiguration (e.g. public storage buckets) is a common cause of breaches', '• less control / visibility; reliance on the provider’s availability', '• data location and GDPR – contract must cover processing and breach notification', '• external services policy needed to manage the provider', 'Conclusion.')]
    ]),
    Q(2, ['The office and warehouse share one internet connection. The router uses NAT and the network uses private IPv4 addresses.'], [
      ['a(i)', 1, 'State the private IPv4 address range that begins with 192.168.', L('Award one mark:', '• 192.168.0.0 – 192.168.255.255 / 192.168.0.0/16 (1)')],
      ['a(ii)', 1, 'State what is meant by an APIPA address.', L('Award one mark:', '• an address in 169.254.x.x automatically assigned when a device cannot reach a DHCP server (1)')],
      ['a(iii)', 2, 'Explain one security benefit of NAT.', L('Award one mark for a benefit and one for expansion:', '• internal addresses are hidden from the internet (1) so devices cannot be directly contacted / targeted from outside (1)')],
      ['b', 3, 'Warehouse handheld scanners and office PCs are on the same network. Describe how VLANs could be used to improve security.', L('Award one mark for each point, up to three marks:', '• create separate VLANs for warehouse devices, office PCs and guests (1)', '• configured on the managed switch (1)', '• traffic between VLANs is controlled by a router / firewall rules (1)', '• so a compromised scanner cannot reach office / finance systems (1)')],
      ['c(i)', 3, 'Describe the role of DNS when a customer visits Kestrel’s website.', L('Award one mark for each point, up to three marks:', '• the browser asks a DNS resolver for the domain name (1)', '• DNS servers look up the domain (hierarchy: root, TLD, authoritative) (1)', '• the IP address of the web server is returned (1)', '• the browser connects to that IP address (1)')],
      ['c(ii)', 2, 'Explain one way DNS could be attacked to harm Kestrel’s customers.', L('Award one mark for an attack and one for expansion:', '• DNS spoofing / cache poisoning (1) customers are sent to a fake site that steals their logins (1)', '• hijacking the domain registration (1) to redirect all traffic (1)')],
      ['d', 2, 'Explain why the warehouse system should only accept connections on the ports it needs.', L('Award up to two marks:', '• every open port is a possible attack vector (1) so closing unused ports reduces the attack surface (1)')],
      ['e', 9, 'Kestrel allows office staff to use their own smartphones to read work email (BYOD). Evaluate the security of this BYOD arrangement.', L(EVAL, '• staff convenience, lower cost to Kestrel', '• devices may lack updates, passcodes or antivirus; may be jailbroken', '• lost / stolen phones expose emails and customer data', '• family members may use the phone', '• Mobile Device Management (MDM) can enforce passcodes, encryption, remote wipe of work data, separate work profiles', '• staff privacy concerns about MDM on personal devices', '• acceptable use / BYOD policy needed; GDPR responsibility remains with Kestrel', 'Conclusion.')]
    ]),
    Q(3, ['A member of the finance team received an email that appeared to come from Kestrel’s managing director, asking for an urgent bank transfer to a new supplier.'], [
      ['a', 2, 'Give two signs that this email may be a phishing attempt.', L('Award one mark each, up to two marks:', '• urgency / pressure (1)', '• unusual request e.g. new bank details (1)', '• sender address slightly different / spoofed (1)', '• spelling / grammar errors (1)', '• request to bypass normal procedures (1)')],
      ['b', 3, 'Describe how a whaling attack differs from a general phishing attack.', L('Award one mark for each point, up to three marks:', '• phishing is sent to many people at once (1)', '• whaling targets / impersonates senior staff such as directors (1)', '• it is researched and personalised to seem genuine (1)', '• aims for high-value results such as large payments / sensitive data (1)')],
      ['c', 3, 'Describe a procedure that would stop staff being tricked into making a false payment.', L('Award one mark for each point, up to three marks:', '• all changes of bank details / new suppliers must be verified (1)', '• by calling the person on a known number, not one in the email (1)', '• payments over a limit need approval from two people (1)', '• staff trained to report suspicious requests (1)')],
      ['d', 2, 'Explain one technical control that reduces the number of phishing emails that reach staff.', L('Award up to two marks:', '• email filtering / spam filters (1) which scan for known phishing links / spoofed senders and quarantine them (1)', '• SPF / DKIM / DMARC (1) which check the sender’s domain is genuine (1)')],
      ['e(i)', 2, 'Explain why staff working from home should use a VPN.', L('Award up to two marks:', '• home / public Wi-Fi may be insecure (1) the VPN encrypts traffic between the laptop and the company network (1)')],
      ['e(ii)', 2, 'State two other risks of staff working from home.', L('Award one mark each, up to two marks:', '• family members / visitors seeing the screen (1)', '• laptop theft from home / travel (1)', '• unsecured home router (1)', '• printing confidential documents at home (1)', '• using personal devices / storage (1)')],
      ['f', 9, 'Kestrel is planning staff IT security training. Evaluate the role of staff training in protecting Kestrel Outdoor from cyber security threats.', L(EVAL, '• people are a major vulnerability: phishing, weak passwords, unsafe practices', '• training helps staff spot phishing / whaling, report incidents quickly, follow policies', '• simulated phishing tests measure progress', '• cheap compared with the cost of a breach; supports GDPR accountability', '• knowledge fades; needs regular refreshers and new-starter training', '• cannot stop all attacks – technical controls (filtering, MFA, backups) still needed', '• warehouse vs office staff need different content', 'Conclusion.')]
    ]),
    Q(4, ['Kestrel’s IT manager is reviewing the backup policy and preparing for possible investigations.'], [
      ['a', 2, 'Give two items that should be included in a backup policy.', L('Award one mark each, up to two marks:', '• what data is backed up (selection) (1)', '• method / type – full, incremental, differential (1)', '• frequency (1)', '• where backups are stored (1)', '• who is responsible (1)', '• how often restores are tested (1)')],
      ['b(i)', 2, 'Explain one advantage of incremental backups.', L('Award up to two marks:', '• only data changed since the last backup is copied (1) so backups are faster / use less storage (1)')],
      ['b(ii)', 2, 'Explain one disadvantage of incremental backups.', L('Award up to two marks:', '• restoring needs the last full backup plus every incremental (1) so recovery is slower / fails if one is missing (1)')],
      ['c(i)', 2, 'An employee is suspected of copying the customer list to a USB stick before leaving. Explain why the investigator should use a write blocker when examining the employee’s PC.', L('Award up to two marks:', '• a write blocker prevents any data being written to the drive (1) so evidence is not changed and remains admissible / reliable (1)')],
      ['c(ii)', 3, 'Describe the evidence on the PC that could show the customer list was copied to a USB stick.', L('Award one mark for each point, up to three marks:', '• USB device history in the registry / system logs (1) showing the device and time it was connected (1)', '• file access times / recently opened files / shortcut (LNK) files (1)', '• matching the time with the employee’s login records (1)')],
      ['d', 2, 'Explain why the investigator must maintain a chain of custody.', L('Award up to two marks:', '• records who handled the evidence, when and what was done (1) so it can be shown the evidence was not tampered with if used in court / disciplinary action (1)')],
      ['e', 9, 'Evaluate whether Kestrel Outdoor should involve the police if the investigation finds that the employee took the customer list.', L(EVAL, '• possible offences under the Computer Misuse Act (unauthorised access / use) and the Data Protection Act (unlawfully obtaining personal data)', '• police involvement may deter others and recover the data', '• evidence must have been collected forensically (chain of custody, hashes) to be usable', '• the breach may also need reporting to the ICO and customers', '• costs, time, publicity and reputational damage', '• alternatives: civil action, injunction, disciplinary process if still employed', 'Conclusion.')]
    ])
  ]));

  /* ───────────── Paper 3: Sixth form college ───────────── */
  papers.push(RA(3, 'Riverside Sixth Form College', 'A college network: guest Wi-Fi, BYOD, Bluetooth, directory services, audits and a forensic investigation.', [
    Q(1, [
      'Riverside Sixth Form College',
      'Riverside Sixth Form College has 1,400 students and 160 staff on one campus.',
      'Staff and students log on using accounts held in a directory service. Students can connect their own devices to a student Wi-Fi network; visitors use a guest network.',
      'Classrooms have interactive displays connected by Bluetooth to teachers’ laptops. The exam office keeps exam papers on a file server.'
    ], [
      ['a(i)', 2, 'Explain one security benefit of using a directory service for user accounts.', L('Award up to two marks:', '• accounts are managed centrally (1) so a leaver can be disabled once and loses access everywhere (1)', '• group policies can be applied to all users / devices (1) enforcing password rules / restrictions (1)')],
      ['a(ii)', 2, 'Explain one Bluetooth vulnerability in the classrooms.', L('Award up to two marks:', '• devices left discoverable (1) so a student could pair with / send content to the display (bluejacking) (1)', '• attackers could access data on a paired laptop (bluesnarfing) (1) if the laptop is not secured (1)')],
      ['a(iii)', 2, 'Explain one way to reduce the Bluetooth risk.', L('Award up to two marks:', '• turn off discoverable mode / Bluetooth when not needed (1) so others cannot find / pair with the device (1)', '• require a PIN / approval for pairing (1) so only the teacher’s laptop connects (1)')],
      ['b(i)', 1, 'State what is meant by a WPS button on a wireless access point.', L('Award one mark:', '• Wi-Fi Protected Setup – lets a device join the network by pressing a button / entering a PIN instead of typing the password (1)')],
      ['b(ii)', 2, 'Explain why WPS should be disabled on the college access points.', L('Award up to two marks:', '• the WPS PIN can be brute-forced quickly (1) giving an attacker the network password / access (1)', '• anyone who can reach the button can connect a device (1)')],
      ['c', 4, 'Describe one threat to the exam papers on the file server and a suitable countermeasure.', L('Award one mark per point, up to four marks:', '• threat e.g. a student gaining access with a staff password (1)', '• countermeasure e.g. restrict the exam folder to exam office staff with MFA (1)', '• how it is enabled e.g. NTFS permissions / security group set by the network manager (1)', '• how it reduces the threat e.g. stolen passwords alone cannot open the folder (1)')],
      ['d', 9, 'Evaluate the security of allowing students to connect their own devices to the student Wi-Fi.', L(EVAL, '• improves learning; reduces college equipment cost', '• unmanaged devices may carry malware or be used for attacks', '• student Wi-Fi should be segmented from staff / admin systems', '• authentication (student logins, WPA2/3-Enterprise) makes users accountable', '• web filtering and monitoring for safeguarding', '• bandwidth and capacity issues', '• acceptable use policy and sanctions', 'Conclusion.')]
    ]),
    Q(2, ['The college network manager is reviewing the network design.'], [
      ['a(i)', 1, 'State one difference between a switch and a hub.', L('Award one mark:', '• a switch sends data only to the intended device (MAC address) whereas a hub sends it to all ports (1)')],
      ['a(ii)', 1, 'State the purpose of a router.', L('Award one mark:', '• to forward packets between different networks (e.g. the LAN and the internet) (1)')],
      ['a(iii)', 2, 'Explain one security benefit of a hierarchical (core / distribution / access) network design.', L('Award up to two marks:', '• traffic can be controlled at the distribution layer (1) so access between departments / VLANs is restricted (1)', '• problems / attacks can be contained to one part of the network (1)')],
      ['b', 3, 'Describe how port security on the access switches could stop a student plugging a laptop into a classroom network socket.', L('Award one mark for each point, up to three marks:', '• the switch port is configured to allow only specific MAC addresses (1)', '• e.g. the MAC of the classroom PC (1)', '• if another device connects, the port is shut down / traffic dropped / an alert sent (1)', 'Accept 802.1X port-based authentication (1).')],
      ['c(i)', 3, 'The college is moving student desktops to thin clients. Describe how a thin client network works.', L('Award one mark per point, up to three marks:', '• the thin client has little processing / storage of its own (1)', '• applications and data run on a central server (1)', '• the client sends keyboard / mouse input and receives the screen display (1)')],
      ['c(ii)', 2, 'State two security benefits of thin clients.', L('Award one mark each, up to two marks:', '• no data stored locally if a device is stolen (1)', '• software / patches managed centrally (1)', '• harder to install malware locally (1)', '• USB ports can be disabled centrally (1)')],
      ['d', 2, 'Explain one risk of relying on the central server for thin clients.', L('Award up to two marks:', '• single point of failure (1) if the server is down / attacked, no thin client can be used (1)')],
      ['e', 9, 'The college is considering moving staff email and file storage to a cloud service. Evaluate the security implications of this move.', L(EVAL, '• provider security, backups and availability; access from anywhere', '• MFA and conditional access available', '• data location / GDPR and contract terms', '• accounts become a target for phishing; access from home devices', '• depends on internet connection', '• staff training and external services policy', '• migration risks – permissions copied incorrectly', 'Conclusion.')]
    ]),
    Q(3, ['A security audit has been carried out to check whether the college is following its IT policies.'], [
      ['a', 2, 'Give two things the audit could check.', L('Award one mark each, up to two marks:', '• password policy is enforced (1)', '• leavers’ accounts are disabled (1)', '• backups run and are tested (1)', '• software is patched / up to date (1)', '• access rights are appropriate (1)', '• staff have completed training (1)')],
      ['b', 3, 'Describe how the Plan-Do-Check-Act cycle applies to the college’s cyber security policy.', L('Award one mark for each point, up to three marks:', '• Plan – identify risks and set policies / controls (1)', '• Do – put the controls in place / train staff (1)', '• Check – audit / monitor whether controls work (1)', '• Act – improve the policy based on the findings (1)')],
      ['c', 3, 'The audit found 12 accounts belonging to staff who had left. Describe the risks this creates.', L('Award one mark per point, up to three marks:', '• ex-staff could still log in remotely (1)', '• attackers could take over unused accounts without anyone noticing (1)', '• access to student personal data / exam papers – a GDPR breach (1)', '• actions cannot be traced to a current person (1)')],
      ['d', 2, 'Explain why the college should have a Data Protection Officer.', L('Award up to two marks:', '• public authorities / organisations processing lots of personal data must appoint one under GDPR (1) to advise on and monitor compliance / be the ICO contact (1)')],
      ['e(i)', 2, 'Explain why staff should lock their screens when leaving a classroom.', L('Award up to two marks:', '• students could use the logged-in account (1) to change marks / see personal data / send emails as the teacher (1)')],
      ['e(ii)', 2, 'State two items that should be in the college’s internet and email use policy for staff.', L('Award one mark each, up to two marks:', '• what personal use is allowed (1)', '• not opening suspicious attachments / reporting phishing (1)', '• not sending personal data unencrypted (1)', '• monitoring of use (1)', '• professional conduct / social media (1)')],
      ['f', 9, 'Evaluate the usefulness of regular security audits for Riverside Sixth Form College.', L(EVAL, '• find gaps between policy and practice (e.g. leavers’ accounts)', '• evidence for GDPR accountability, insurers and Ofsted / governors', '• drive improvements through PDCA', '• internal audits are cheaper; external audits are more independent', '• take staff time and cost; findings must be acted on', '• point-in-time – continuous monitoring also needed', 'Conclusion.')]
    ]),
    Q(4, ['A student is suspected of accessing a teacher’s laptop and changing coursework marks. The college has asked its network manager to investigate.'], [
      ['a', 2, 'Give two offences under the Computer Misuse Act 1990.', L('Award one mark each, up to two marks:', '• unauthorised access to computer material (1)', '• unauthorised access with intent to commit further offences (1)', '• unauthorised acts with intent to impair / modify a computer (1)', '• making / supplying tools for computer misuse (1)')],
      ['b(i)', 2, 'Explain why the network manager should make a forensic image of the laptop rather than examining it directly.', L('Award up to two marks:', '• examining it directly changes data such as access times (1) so the image is examined instead and the original is preserved (1)')],
      ['b(ii)', 2, 'Explain one piece of evidence on the college network that could show who changed the marks.', L('Award up to two marks:', '• authentication / logon logs (1) show which account logged in and from which device at the time the marks changed (1)', '• database / application audit log (1) shows the account that edited the record (1)')],
      ['c(i)', 2, 'Explain what is meant by a false positive in a forensic investigation.', L('Award up to two marks:', '• something that appears to be evidence of the incident (1) but turns out to be innocent / unrelated, e.g. a legitimate login by the teacher (1)')],
      ['c(ii)', 3, 'Describe how the network manager should record findings during the analysis.', L('Award one mark per point, up to three marks:', '• record each step, tool and setting used (1)', '• time-stamped notes / screenshots of what is found (1)', '• note any alterations made and why (1)', '• keep records so another investigator could repeat the analysis (1)')],
      ['d', 2, 'Explain one internal indicator of compromise the network manager might find.', L('Award up to two marks:', '• logins at unusual times / from unusual devices (1) suggesting the account was used by someone else (1)', '• new / unknown software e.g. a keylogger (1) used to capture the teacher’s password (1)')],
      ['e', 9, 'Evaluate the difficulties of carrying out a fair and reliable forensic investigation within the college rather than using an external specialist.', L(EVAL, '• internal staff know the systems and can act quickly and cheaply', '• may lack forensic training / tools (write blockers, imaging software)', '• risk of altering evidence or breaking chain of custody', '• possible conflict of interest / bias; network manager’s own controls may be at fault', '• fairness to the student – evidence must be reliable for sanctions / police', '• external specialists cost more but are independent and evidence is more credible', 'Conclusion.')]
    ])
  ]));

  /* ───────────── Paper 4: Law firm ───────────── */
  papers.push(RA(4, 'Hale & Sutton Solicitors', 'A law firm: confidentiality, insider threats, email encryption, disaster recovery and network forensics.', [
    Q(1, [
      'Hale & Sutton Solicitors',
      'Hale & Sutton is a firm of solicitors with 60 staff in two offices. It handles property sales, wills and family law cases.',
      'Client files are stored on a server in a locked room at the head office. Solicitors send documents to clients and other law firms by email.',
      'The firm is a common target of criminals who try to divert money from property sales.'
    ], [
      ['a(i)', 2, 'Explain one reason why law firms are targeted by cyber criminals.', L('Award up to two marks:', '• they handle large sums of client money in property sales (1) which criminals try to divert with fake bank details (1)', '• they hold highly confidential personal data (1) which can be sold / used for blackmail (1)')],
      ['a(ii)', 2, 'Explain what is meant by an internal threat.', L('Award up to two marks:', '• a threat from people inside the organisation, such as staff / contractors (1) whether deliberate (sabotage / theft) or accidental (mistakes / loss) (1)')],
      ['a(iii)', 2, 'Explain one accidental internal threat to client data at Hale & Sutton.', L('Award up to two marks:', '• sending an email to the wrong recipient (1) disclosing confidential client documents (1)', '• leaving a laptop / papers on a train (1) exposing client data (1)')],
      ['b(i)', 1, 'State what is meant by end-to-end encryption (E2EE).', L('Award one mark:', '• data is encrypted on the sender’s device and only decrypted on the recipient’s device, so no one in between can read it (1)')],
      ['b(ii)', 2, 'Explain one drawback of the firm using end-to-end encrypted email with clients.', L('Award up to two marks:', '• clients may need extra software / accounts (1) which some clients find difficult to use (1)', '• the firm cannot scan encrypted content for malware (1)')],
      ['c', 4, 'Describe one threat to money transfers in property sales and a suitable countermeasure.', L('Award one mark per point, up to four marks:', '• threat: email interception / spoofing – criminals send fake bank details (1)', '• countermeasure: confirm bank details by phone on a known number / in person (1)', '• tell clients at the start that bank details will never change by email (1)', '• so a fake email is spotted before money is sent (1)')],
      ['d', 9, 'Evaluate the risks to Hale & Sutton from insider threats and how they could be managed.', L(EVAL, '• staff have legitimate access to sensitive files – hard to detect misuse', '• deliberate: theft of client data for a rival / criminals; sabotage by unhappy staff', '• accidental: misdirected emails, weak passwords, lost devices', '• controls: least privilege / RBAC, monitoring and audit logs, DLP software, disabling USB, prompt removal of leavers’ access', '• training and a clear acceptable use policy; vetting staff', '• monitoring must be proportionate and staff informed (privacy)', 'Conclusion.')]
    ]),
    Q(2, ['The two offices are connected by a WAN. The IT manager is reviewing how the network is configured.'], [
      ['a(i)', 1, 'State one difference between a LAN and a WAN.', L('Award one mark:', '• a LAN covers a small area such as one building, a WAN connects networks across a wide geographic area (1)')],
      ['a(ii)', 1, 'State one function of a firewall.', L('Award one mark:', '• filters traffic using rules – allowing or blocking by port / IP address / protocol (1)')],
      ['a(iii)', 2, 'Explain one difference between an extranet and an intranet.', L('Award up to two marks:', '• an intranet is for internal staff only (1) an extranet also gives controlled access to authorised outsiders such as clients / other firms (1)')],
      ['b', 3, 'Hale & Sutton wants to give clients secure access to view their case documents. Describe how a secure client portal (extranet) could work.', L('Award one mark per point, up to three marks:', '• clients log in with unique credentials and MFA (1)', '• access controls show each client only their own documents (1)', '• connection encrypted with HTTPS (1)', '• activity logged / documents can be revoked (1)')],
      ['c(i)', 3, 'Describe the TCP/IP four-layer model.', L('Award one mark per point, up to three marks:', '• application layer – protocols used by programs e.g. HTTP, SMTP (1)', '• transport layer – TCP / UDP split data into segments, ports, error checking (1)', '• internet layer – IP addressing and routing of packets (1)', '• link / network access layer – physical transmission over the network hardware (1)')],
      ['c(ii)', 2, 'State two items of information in an IP packet header.', L('Award one mark each, up to two marks:', '• source IP address (1)', '• destination IP address (1)', '• time to live (1)', '• protocol (1)', '• header checksum (1)')],
      ['d', 2, 'Explain how TLS protects email being sent between mail servers.', L('Award up to two marks:', '• encrypts the connection between the servers (1) so the email cannot be read if intercepted in transit (1)')],
      ['e', 9, 'Evaluate the use of a software-defined network (SDN) and virtualised servers to manage the network across the two offices.', L(EVAL, '• central control of network policies across both sites; quick changes', '• easier segmentation and consistent security rules', '• virtual servers reduce hardware, improve backup / snapshots and recovery', '• the SDN controller / hypervisor becomes a high-value target – single point of failure', '• needs specialist skills; cost of change', '• misconfiguration affects everything at once', 'Conclusion.')]
    ]),
    Q(3, ['The firm is writing a disaster recovery policy. A flood at the head office last year damaged the server room.'], [
      ['a', 2, 'Give two items in a disaster recovery policy.', L('Award one mark each, up to two marks:', '• purpose and scope (1)', '• triage / priorities for restoring systems (1)', '• roles and responsibilities (1)', '• contact lists (1)', '• monitoring and reporting (1)')],
      ['b', 3, 'Describe how the firm could prioritise which systems are restored first after a disaster.', L('Award one mark per point, up to three marks:', '• identify critical systems e.g. case management, email, client accounts (1)', '• consider legal / client deadlines e.g. completions (1)', '• set recovery time objectives for each (1)', '• restore in order of business impact (1)')],
      ['c', 3, 'Describe the difference between a hot site and a cold site for disaster recovery.', L('Award one mark per point, up to three marks:', '• a hot site has equipment and up-to-date data ready to take over almost immediately (1)', '• a cold site is space / power / connectivity only (1)', '• equipment and data must be installed / restored, so recovery takes much longer (1)', '• hot sites are much more expensive (1)')],
      ['d', 2, 'Explain why the disaster recovery plan must be tested.', L('Award up to two marks:', '• to check backups can actually be restored and staff know their roles (1) so problems are found before a real disaster (1)')],
      ['e(i)', 2, 'Explain one risk of storing backups on removable media taken home by the office manager.', L('Award up to two marks:', '• the media could be lost / stolen (1) exposing confidential client data unless encrypted (1)')],
      ['e(ii)', 2, 'State two ways to securely dispose of old hard drives from the flooded server.', L('Award one mark each, up to two marks:', '• physical destruction / shredding (1)', '• degaussing (1)', '• secure overwriting / wiping software (1)', '• certified disposal company with certificate of destruction (1)')],
      ['f', 9, 'Evaluate whether Hale & Sutton should move its server and backups to a cloud provider to improve disaster recovery.', L(EVAL, '• data stored off-site in resilient data centres – unaffected by local flood / fire', '• quick recovery; staff can work from anywhere', '• dependent on internet links; outages stop work', '• confidentiality of client data – encryption, provider access, data location, legal professional obligations', '• ongoing costs vs replacing equipment', '• contracts / exit plans, external services policy', 'Conclusion.')]
    ]),
    Q(4, ['A solicitor reported that a client’s completion money was sent to a criminal’s account after the client received an email with changed bank details. The IT manager starts an investigation.'], [
      ['a', 2, 'Give two sources of evidence on the network that could help the investigation.', L('Award one mark each, up to two marks:', '• email server logs / message headers (1)', '• firewall / proxy logs (1)', '• authentication / logon logs (1)', '• mailbox rules / forwarding settings (1)')],
      ['b(i)', 2, 'Explain what network forensics involves.', L('Award up to two marks:', '• capturing / analysing network traffic and logs (1) to find how an attacker got in / where data went (1)')],
      ['b(ii)', 2, 'Explain why the email headers are useful evidence.', L('Award up to two marks:', '• show the real sending server / IP address and route (1) so a spoofed email can be identified (1)')],
      ['c(i)', 2, 'The investigation finds a hidden rule in the solicitor’s mailbox forwarding emails to an outside address. Explain what this suggests.', L('Award up to two marks:', '• the solicitor’s account was compromised (1) so the criminal could read emails about the sale and time the fake email (1)')],
      ['c(ii)', 3, 'Describe the immediate actions the IT manager should take.', L('Award one mark per point, up to three marks:', '• remove the forwarding rule and reset the password (1)', '• enforce MFA / sign out all sessions (1)', '• preserve logs and evidence before changes / record what is done (1)', '• inform the bank, police / Action Fraud, client and the ICO as required (1)')],
      ['d', 2, 'Explain one recommendation the security report should make to prevent this happening again.', L('Award up to two marks:', '• enable MFA on email (1) so stolen passwords alone cannot be used (1)', '• alerts for new forwarding rules (1) so compromise is noticed quickly (1)')],
      ['e', 9, 'Evaluate the effectiveness of multi-factor authentication in protecting Hale & Sutton’s email accounts.', L(EVAL, '• stops most attacks using stolen / guessed passwords', '• methods: app codes, push, hardware keys, SMS – different strengths (SMS can be SIM-swapped)', '• MFA fatigue / push-bombing; phishing kits can capture codes – hardware keys / number matching help', '• staff inconvenience; lost phones; support costs', '• must cover all access routes (legacy protocols bypass MFA)', '• one layer only – training, filtering and payment checks still needed', 'Conclusion.')]
    ])
  ]));

  /* ───────────── Paper 5: Manufacturer with IoT ───────────── */
  papers.push(RA(5, 'Apex Components (smart factory)', 'A factory with IoT sensors: segmentation, OWASP, security by design, external services and a full incident.', [
    Q(1, [
      'Apex Components',
      'Apex Components makes parts for car manufacturers. Its factory uses IoT sensors and robotic machines that are monitored from an office network.',
      'Engineers can access the machine control system remotely to fix faults. Designs for customers are stored on a file server and shared through a cloud service.',
      'Apex has been told by a customer that it must meet ISO 27001 to keep its contract.'
    ], [
      ['a(i)', 2, 'Draw a network diagram showing the office network and the factory (IoT) network as separate segments, connected through a firewall to each other and to the internet.', L('Award one mark for each, up to two marks:', '• office and factory / IoT networks shown as separate segments / switches / VLANs (1)', '• a firewall shown between the segments and between the networks and the internet / router (1)'), { diagram: true }],
      ['a(ii)', 2, 'Explain one vulnerability of IoT sensors.', L('Award up to two marks:', '• default / hard-coded passwords (1) easily found online, letting attackers control them (1)', '• rarely updated / patched (1) so known weaknesses stay open (1)', '• limited processing power for encryption (1) so data may be sent in plain text (1)')],
      ['a(iii)', 2, 'Explain why the factory network should be separated from the office network.', L('Award up to two marks:', '• an infection in the office (e.g. from email) cannot reach the machines (1) so production is not stopped / machines cannot be sabotaged (1)')],
      ['b(i)', 1, 'State what is meant by cyberwarfare.', L('Award one mark:', '• attacks by / on behalf of a nation state on another country’s systems / infrastructure (1)')],
      ['b(ii)', 2, 'Explain one impact on Apex if its machines were sabotaged.', L('Award up to two marks:', '• operational loss (1) production stops and orders are late (1)', '• faulty parts produced (1) causing safety issues / loss of the customer contract (1)')],
      ['c', 4, 'Describe how remote access for engineers could be made secure.', L('Award one mark per point, up to four marks:', '• use a VPN / remote access gateway rather than open ports (1)', '• require MFA for engineers (1)', '• limit access to specific machines / times (least privilege) (1)', '• log and monitor all sessions (1)', '• disable access when not needed / approval needed for each session (1)')],
      ['d', 9, 'Evaluate the benefits and risks to Apex Components of using IoT sensors in its factory.', L(EVAL, 'Benefits:', '• real-time monitoring, predictive maintenance, less downtime, quality data', 'Risks:', '• large attack surface; weak device security; physical tampering', '• attackers could stop production or alter settings', '• data volumes and privacy of production data', 'Mitigation:', '• segmentation, change default passwords, patching, monitoring, choose secure-by-design devices', 'Conclusion.')]
    ]),
    Q(2, ['Apex is working towards ISO 27001 and reviewing how its systems are designed.'], [
      ['a(i)', 1, 'State what ISO 27001 is.', L('Award one mark:', '• an international standard for an information security management system (ISMS) (1)')],
      ['a(ii)', 1, 'State one principle of security by design.', L('Award one mark:', '• expect attacks / assume breach (1)', '• fewest privileges (1)', '• no reliance on secrecy (1)', '• defence in depth (1)')],
      ['a(iii)', 2, 'Explain the principle of least privilege.', L('Award up to two marks:', '• users / programs get only the access they need for their role (1) so the damage from a compromised account is limited (1)')],
      ['b', 3, 'Apex’s customers log in to a web portal to track orders. Describe how the OWASP Top 10 could help Apex secure the portal.', L('Award one mark per point, up to three marks:', '• OWASP publishes the most critical web application risks (1)', '• e.g. injection, broken access control, security misconfiguration (1)', '• developers check / test the portal against each risk (1)', '• and follow OWASP guidance to fix them (1)')],
      ['c(i)', 3, 'Describe how a firewall could be configured to protect the factory network.', L('Award one mark per point, up to three marks:', '• default deny – block all traffic unless allowed (1)', '• allow only required traffic from the office monitoring PCs to the machines on specific ports (1)', '• block direct internet access to / from the IoT devices (1)', '• log and alert on blocked attempts (1)')],
      ['c(ii)', 2, 'State two network services that should be disabled on the IoT devices if not needed.', L('Award one mark each, up to two marks:', '• Telnet (1)', '• FTP (1)', '• UPnP (1)', '• web admin interface over HTTP (1)', '• SSH from outside (1)')],
      ['d', 2, 'Explain why the robotic machines’ operating systems are difficult to patch.', L('Award up to two marks:', '• machines must run continuously / updates cause downtime (1)', '• the manufacturer may not support updates / updates may break the control software (1)')],
      ['e', 9, 'Evaluate the value to Apex Components of achieving ISO 27001 certification.', L(EVAL, '• required to keep the customer contract; helps win new contracts', '• structured approach to managing risk (PDCA), policies and audits', '• independent third-party certification gives assurance', '• cost of consultants, audits, staff time; ongoing surveillance audits', '• certification does not guarantee no breaches; risk of “tick-box” compliance', 'Conclusion.')]
    ]),
    Q(3, ['Apex shares customer designs through a cloud file-sharing service and uses an external company for IT support.'], [
      ['a', 2, 'Give two items an external services policy should include.', L('Award one mark each, up to two marks:', '• which cloud / external services are approved (1)', '• security requirements for suppliers (1)', '• data protection / contract terms (1)', '• who manages supplier access (1)', '• support / service level expectations (1)', '• exit / termination arrangements (1)')],
      ['b', 3, 'Describe the risks of sharing designs through a cloud file-sharing service.', L('Award one mark per point, up to three marks:', '• links could be shared publicly / forwarded (1)', '• account compromise exposes all shared designs (1)', '• provider breach / data location (1)', '• intellectual property loss if a competitor obtains designs (1)')],
      ['c', 3, 'Describe how due diligence should be carried out before choosing the IT support company.', L('Award one mark per point, up to three marks:', '• check certifications e.g. ISO 27001 / Cyber Essentials (1)', '• ask for references / past performance (1)', '• review their security practices and staff vetting (1)', '• agree a contract covering confidentiality, access and data protection (1)')],
      ['d', 2, 'Explain one risk of the IT support company having permanent remote access to Apex’s systems.', L('Award up to two marks:', '• if the support company is breached (1) attackers can use its access to reach Apex (supply-chain attack) (1)')],
      ['e(i)', 2, 'Explain one reason why Apex should monitor its network traffic.', L('Award up to two marks:', '• to spot unusual traffic, e.g. large uploads at night (1) which may show data theft / malware early (1)')],
      ['e(ii)', 2, 'State two network monitoring or management tools.', L('Award one mark each, up to two marks:', '• packet sniffer / Wireshark (1)', '• intrusion detection system (1)', '• SNMP monitoring tool (1)', '• SIEM / log management (1)', '• bandwidth monitor (1)')],
      ['f', 9, 'Evaluate the use of an intrusion detection system (IDS) on Apex’s networks.', L(EVAL, '• detects known attack signatures and unusual behaviour', '• alerts staff early; useful evidence for investigations', '• false positives can overwhelm staff; false negatives miss new attacks', '• IDS only alerts – an IPS can block but may stop legitimate production traffic', '• needs tuning, skilled staff / a managed service; cost', '• IoT traffic is predictable, which helps anomaly detection', 'Conclusion.')]
    ]),
    Q(4, ['One morning several factory machines stopped and a message demanded payment. Apex activates its incident response policy.'], [
      ['a', 2, 'Draw a simple flowchart showing the first steps of Apex’s incident response: detect the incident, decide whether it is serious, contain it, and inform the right people.', L('Award one mark for each, up to two marks:', '• correct sequence: detect / report → assess → contain → inform (1)', '• a decision (diamond) for “serious?” with Yes / No paths, e.g. No → log and monitor (1)'), { diagram: true }],
      ['b(i)', 2, 'Explain why communications are an important part of the incident response policy.', L('Award up to two marks:', '• customers, staff, insurers and regulators need accurate, timely information (1) to protect reputation / meet legal duties (1)')],
      ['b(ii)', 2, 'Explain why the incident response team should use a communication channel that is separate from the company network.', L('Award up to two marks:', '• attackers may be monitoring email / the network may be down (1) so phones / an out-of-band channel keep the response confidential and working (1)')],
      ['c(i)', 2, 'Explain why a snapshot of the affected virtual servers should be taken before they are restored.', L('Award up to two marks:', '• preserves the state of the server, including evidence of the attack (1) so it can be analysed after the system is back in use (1)')],
      ['c(ii)', 3, 'Describe how the investigator should analyse the suspect system to find how the attackers got in.', L('Award one mark per point, up to three marks:', '• work on a verified copy / image, not the original (1)', '• review logs for the first sign of compromise (timeline) (1)', '• look for indicators of compromise e.g. new accounts, unusual processes, remote connections (1)', '• compare with known attack patterns / threat intelligence (1)')],
      ['d', 2, 'Explain one way the security report could improve Apex’s IT policies.', L('Award up to two marks:', '• identify the gap that allowed the attack e.g. no MFA on remote access (1) and update the remote access policy to require it (1)')],
      ['e', 9, 'Evaluate the impact of this incident on Apex Components.', L(EVAL, '• operational loss – production stopped, missed deliveries to car manufacturers', '• financial loss – recovery costs, penalties, possible ransom, lost contracts', '• reputational loss – customers question security; ISO 27001 status at risk', '• intellectual property loss if designs were stolen', '• legal – GDPR if personal data affected', '• impact reduced by a tested incident response plan, backups and insurance', 'Conclusion: overall seriousness and which impact is greatest.')]
    ])
  ]));

  window.BIZ_PAPERS = (window.BIZ_PAPERS || []).concat(papers);
})();
